####################################################################################################
# Function to tidy up participants (pid), vaccinations (expo), and immunogenicity (sero) data frames
####################################################################################################

fun_dgsk_tidydfs <- function(x, study_id = "10555", cdi = FALSE, dfs = "pid") {
  # Arguments:
  # - x: (list of data frames) A list of data frames for a specific study, generated by the 
  # `fun_dgsk_readdfs` function.
  # - study_id: (string) The unique identifier for the study being processed. 
  # - cdi: (logical) Indicates whether the study data is in CDI format (common in newer studies).
  # - dfs: (string) Specifies which data frame to tidy, must be one of: "pid", "expo", "sero_all".
  #
  # Output:
  # - x: (data frame) The tidied data frame for the specified `dfs` type.
  
  # Tidy up the `pid` data frame ===================================================================
  
  if(dfs == "pid") {
    if(cdi == FALSE) {
      # Process `pid` data frame for non-CDI format
      x$pid <- x$pid %>%
        select(pid, center, cty_nam, treatmnt, elig_ma) %>%
        # Join with demographic data
        left_join(select(x$demo, pid, age_unit, age, date_ref, sex), by = join_by(pid))  
    } else {
      # Process `pid` data frame for CDI format
      x$pid <- x$pid %>%
        select(usubjid, siteid, country, aage, aageu, sex, rficdt, actarm, pps01fl) %>%
        # Rename columns to match non-CDI format
        rename(pid = usubjid, center = siteid, cty_nam = country, treatmnt = actarm, 
               elig_ma = pps01fl, age = aage, age_unit = aageu, sex = sex, date_ref = rficdt)
    }
    
    # Tidying for `pid` data frame
    df_pid <- x$pid %>%
      mutate(study = study_id) %>%
      # Estimate date of birth from reference date and age             
      mutate(age_ref_date = fun_dgsk_tidydates(date_ref),
             age_ref = case_when(
               age_unit %in% c("Y", "YEARS") ~ as.numeric(age)*365,
               age_unit %in% c("M", "MONTHS") ~ as.numeric(age)*30,
               age_unit %in% c("W", "WEEKS") ~ as.numeric(age)*7,
               age_unit %in% c("D", "DAYS") ~ as.numeric(age)*1, 
               .default = NA), 
             birth_date = age_ref_date - age_ref,
             birth_week = week(birth_date),
             birth_week = case_when(birth_week == 53 ~ 52, .default = birth_week)) %>%
      # Tidy rct groups
      mutate(treatmnt = tolower(treatmnt)) %>%
      # Tidy country names 
      left_join(dics$countries, by = join_by(cty_nam, study)) %>%
      mutate(country = country_tidy) %>%
      # Tidy center: Eliminate leading white spaces
      mutate(center = gsub("^\\s+", "", center)) %>%
      # Tidy NAs
      mutate(across(all_of(c("pid", "age_unit", "date_ref", "sex", "center", "country", 
                             "treatmnt")), ~ na_if(.x, "")))  %>%
      # Ensure only one age per individual (use the earliest age entry)
      group_by(study, pid) %>%
      mutate(age_no = rank(age_ref_date)) %>%
      filter(age_no == 1) %>%
      ungroup() %>%
      # Eliminate early exclusion individuals (those without center data)
      filter(!(is.na(center))) %>%
      # Tidy names and select relevant variables
      rename(rct_group = treatmnt, eligibility = elig_ma) %>%
      select(study, pid, center, country, rct_group, eligibility, age_ref, age_unit, sex, birth_date, 
             birth_week, age_ref_date) %>%
      # Arrange by study and PID
      arrange(study, as.numeric(pid)) 
  
    return(df_pid)
    
  # Tidy up the `expo` data frame ==================================================================
  } else if(dfs == "expo") {
    
    if(cdi == TRUE) {
      # Process `expo` data frame for CDI format
      x$expo <- x$expo %>%
        select(usubjid, aextrt, adt, trt01an, esfl) %>%
        # Rename columns to match non-CDI format
        rename(pid = usubjid, vaccine = aextrt, p_rdat = adt, v_adm = esfl)
    }
    
    # Tidying for `expo` data frame
    df_expo_all <- x$expo %>%
      mutate(study = study_id) %>%
      select(study, pid, vaccine, p_rdat, v_adm) %>%
      # Tidy vaccination dates: Reformat 
      mutate(vac_date = fun_dgsk_tidydates(p_rdat)) %>%
      # Tidy vaccine names 
      left_join(dics$vaccines, by = join_by(study, vaccine)) %>%
      mutate(vaccine = vaccine_tidy) %>%
      # Tidy names and select relevant variables
      rename(vac_name = vaccine) %>%
      select(study, pid, vac_name, v_adm, vac_date) %>%
      distinct()
    
    return(df_expo_all)
    
  # Tidy up the `sero_all` data frame ==============================================================
  } else if(dfs == "sero_all") {
   
    if(cdi == FALSE) {
      # Process and merge `sero` data frame with serology date data for non-CDI format
      df_dat_sero <- x$dates %>%
        select(pid, raw_date, activity, type_lst) %>%
        # Select only dates for blood and serology
        filter(type_lst %in% c("BL", "SER"))
      
      x$sero <- x$sero %>%
        full_join(df_dat_sero, by = join_by(activity, pid))
    } else {
      # Process `sero` data frame for CDI format
      x$sero <- x$sero %>%
        select(usubjid, avisitn, parcat1, param, aval, adt, cutoff01) %>%
        rename(pid = usubjid, method = parcat1, seroname = param, num_res = aval, raw_date = adt,
               activity = avisitn, cut_off = cutoff01) %>%
        mutate(unit = NA) %>%
        filter(str_detect(seroname, "LOG10", negate = T)) 
    }
    
    # Tidying for `sero_all` data frame
    df_sero_all <- x$sero %>%
      mutate(study = study_id) %>%
      select(study, pid, method, seroname, num_res, raw_date, activity, cut_off, unit) %>%
      # Tidy serology names and methods 
      left_join(dics$seronames, by = join_by(study, method, seroname, cut_off, unit)) %>%
      mutate(seroname = seroname_tidy,
             method = method_tidy) %>%
      filter(!is.na(seroname)) %>%
      # Tidy blood sampling date: Reformat 
      mutate(raw_date = na_if(raw_date, ""),
             imm_date = fun_dgsk_tidydates(raw_date),
             # We are expecting to get some NAs after coercion:
             num_res = suppressWarnings(as.numeric(num_res))) %>%
      # Select relevant variables
      rename(imm_val = num_res, imm_met = method, imm_sero = seroname) %>%
      select(study, pid, imm_val, imm_met, imm_sero, imm_date, activity)
  
    return(df_sero_all)
  } else {
    print("Error: Invalid argument for `dfs`. Must be one of: 'pid', 'expo', 'sero_all'.")
  }
}

